import java.util.*;

class Solution {
    static int longestStreak(int[] days) {
        Set<Integer> active = new HashSet<>();
        for (int day : days) active.add(day);
        int best = 0;
        for (int day : active) {
            if (active.contains(day - 1)) continue;
            int length = 1;
            while (active.contains(day + length)) length++;
            best = Math.max(best, length);
        }
        return best;
    }
}
